CREATE OR REPLACE PACKAGE BODY rolling AS

  FUNCTION rolling_balance(p_rows IN t_txn_cur) RETURN rolling_runningrow_nt PIPELINED PARALLEL_ENABLE(PARTITION p_rows BY HASH(country_code))
