            l_cur_country := l_r_buf(i_r).country_code;
            l_total := 0;
          END IF;
        END IF;
        l_total := (l_total + l_r_buf(i_r).amount);
        PIPE ROW(rolling_runningrow_obj(l_r_buf(i_r).country_code, l_r_buf(i_r).ts, l_total));
      END LOOP;
    END LOOP;
    CLOSE p_rows;
